          "title": "First-Principles: Primal Soft Margin (Hinge + L2) & Audit Zona Slack",
          "language": "python",
          "filename": "11_1_primal_soft_margin_hinge.py",
          "code": "import numpy as np\n\nrng = np.random.default_rng(42)\n\n# Dataset klasifikasi biner 2D dengan sedikit tumpang tindih & 4 outlier label\nn_per_class = 90\nX_neg = rng.normal(loc=[-1.4, -1.1], scale=[0.9, 0.9], size=(n_per_class, 2))\nX_pos = rng.normal(loc=[+1.4, +1.1], scale=[0.9, 0.9], size=(n_per_class, 2))\nX = np.vstack([X_neg, X_pos])\ny = np.concatenate([-np.ones(n_per_class), np.ones(n_per_class)])\n\n# Sisipkan 4 outlier berlabel terbalik (membuat Hard Margin infeasible!)\ny[[3, 17]] = +1.0\ny[[n_per_class + 5, n_per_class + 22]] = -1.0\n\n# Split latih / uji deterministik\nperm = rng.permutation(len(y))\ntr_idx, te_idx = perm[:140], perm[140:]\nX_tr, y_tr = X[tr_idx], y[tr_idx]\nX_te, y_te = X[te_idx], y[te_idx]\n\ndef fit_primal_soft_margin_svm(X_mat, y_vec, C_val, steps=3500):\n    \"\"\"Minimasi 0.5*||w||^2 + C * sum(max(0, 1 - y_i*(w^T x_i + b))) via subgradient.\"\"\"\n    n_samples, n_dim = X_mat.shape\n    w = np.zeros(n_dim)\n    b = 0.0\n    best_obj = np.inf\n    best_w, best_b = w.copy(), b\n    for t in range(1, steps + 1):\n        margins = y_vec * (X_mat @ w + b)\n        active = margins < 1.0\n        # Subgradien terhadap w dan b\n        grad_w = w - C_val * (X_mat[active].T @ y_vec[active])\n        grad_b = -C_val * np.sum(y_vec[active])\n        eta = 0.5 / (1.0 + 0.03 * t * max(1.0, C_val))\n        w = w - eta * grad_w\n        b = b - eta * grad_b\n        if t % 25 == 0 or t == steps:\n            slacks = np.maximum(0.0, 1.0 - y_vec * (X_mat @ w + b))\n            obj = 0.5 * float(np.dot(w, w)) + C_val * float(np.sum(slacks))\n            if obj < best_obj:\n                best_obj = obj\n                best_w, best_b = w.copy(), float(b)\n    return best_w, best_b\n\nprint(\"=== Pengaruh Parameter C pada Geometri Margin & Distribusi Slack (Primal Hinge + L2) ===\")\nprint(\"    C  | ||w||_2 | Margin 2/||w|| | xi=0 | 0<xi<1 | xi>=1 | AccTr | AccTe | ObjSlack==ObjHinge\")\nprint(\"-\" * 94)\nfor C_val in (0.05, 1.0, 50.0):\n    w_hat, b_hat = fit_primal_soft_margin_svm(X_tr, y_tr, C_val)\n    norm_w = float(np.linalg.norm(w_hat))\n    geom_margin = 2.0 / norm_w\n    func_margins = y_tr * (X_tr @ w_hat + b_hat)\n    xi = np.maximum(0.0, 1.0 - func_margins)\n    n_safe = int(np.sum(xi <= 1e-6))\n    n_in_margin = int(np.sum((xi > 1e-6) & (xi < 1.0)))\n    n_mis = int(np.sum(xi >= 1.0))\n    acc_tr = float(np.mean(np.sign(X_tr @ w_hat + b_hat) == y_tr))\n    acc_te = float(np.mean(np.sign(X_te @ w_hat + b_hat) == y_te))\n    # Verifikasi identitas objektif Primal Slack vs Regularized Hinge Loss\n    obj_slack = 0.5 * float(np.dot(w_hat, w_hat)) + C_val * float(np.sum(xi))\n    obj_hinge = 0.5 * float(np.dot(w_hat, w_hat)) + C_val * float(np.sum(np.maximum(0.0, 1.0 - func_margins)))\n    eq_gap = abs(obj_slack - obj_hinge)\n    print(f\"{C_val:6.2f} | {norm_w:7.4f} | {geom_margin:14.4f} | {n_safe:4d} | {n_in_margin:6d} | {n_mis:5d} | {acc_tr:5.3f} | {acc_te:5.3f} | gap={eq_gap:.1e}\")",
          "expectedOutput": "=== Pengaruh Parameter C pada Geometri Margin & Distribusi Slack (Primal Hinge + L2) ===\n    C  | ||w||_2 | Margin 2/||w|| | xi=0 | 0<xi<1 | xi>=1 | AccTr | AccTe | ObjSlack==ObjHinge\n----------------------------------------------------------------------------------------------\n  0.05 |  0.9039 |         2.2127 |  103 |     32 |     5 | 0.964 | 0.975 | gap=0.0e+00\n  1.00 |  1.2852 |         1.5562 |  120 |     15 |     5 | 0.964 | 0.975 | gap=0.0e+00\n 50.00 |  1.3005 |         1.5379 |  120 |     15 |     5 | 0.964 | 0.975 | gap=0.0e+00",
          "actualOutput": "=== Pengaruh Parameter C pada Geometri Margin & Distribusi Slack (Primal Hinge + L2) ===\n    C  | ||w||_2 | Margin 2/||w|| | xi=0 | 0<xi<1 | xi>=1 | AccTr | AccTe | ObjSlack==ObjHinge\n----------------------------------------------------------------------------------------------\n  0.05 |  0.9039 |         2.2127 |  103 |     32 |     5 | 0.964 | 0.975 | gap=0.0e+00\n  1.00 |  1.2852 |         1.5562 |  120 |     15 |     5 | 0.964 | 0.975 | gap=0.0e+00\n 50.00 |  1.3005 |         1.5379 |  120 |     15 |     5 | 0.964 | 0.975 | gap=0.0e+00",
